product-workflow-states.code:
type Status =
  | { kind: 'loading' }
  | { kind: 'empty' }
  | { kind: 'error'; message: string }
  | { kind: 'success'; orders: Order[] }

function OrderList({ status, onRetry }: Props) {
  switch (status.kind) {
    case 'loading':
      return <Spinner aria-busy="true" aria-label="Loading orders" />
    case 'empty':
      return <Empty title="No orders yet" hint="They'll appear here after checkout." />
    case 'error':
      return (
        <div role="alert">
          <p>{status.message}</p>
          <button onClick={onRetry}>Retry</button>
        </div>
      )
    case 'success':
      return <ul>{status.orders.map((o) => <OrderRow key={o.id} order={o} />)}</ul>
  }
}

