// Rendering all five states, not just success
// Mission: Take one real user-facing workflow (a checkout step, a form submit, a feed load) and build component_state_matrix_and_accessibility_packet.md: every UI state the component can hold — loading, empty, error, disabled, success — each with its trigger, its visible+accessible render, and the keyboard/screen-reader behavior. Then prove one failing state path with a checklist.
// Novice workflow:
// 1. Enumerate loading, empty, error, success, denied, and rollback states before coding.
// 2. Identify the semantic HTML, keyboard, data, auth, and responsive boundary under test.
// 3. Implement only renderStatus at the TODO.
// 4. Run every fixture, add one failure or accessibility case, and retain it as a regression.
// 5. Explain what must still be proven in a real browser and production-like environment.
// Evidence checklist:
// 1. List every state your component can REACH (loading, empty, error, disabled, success). For each, point to the exact render. Any reachable state with no render is a silent failure — fix it.
// 2. Force the error state on purpose (block the network, return a 500). Confirm a message appears AND a screen reader announces it via role="alert" or aria-live — not just a visual banner.
// 3. Force the empty state (a query with zero results). Confirm it renders a designed empty state with a hint, not a blank screen that reads as broken.
// 4. Tab to the trigger with the keyboard only, activate it, and confirm it disables in-flight (no double submit) and that focus lands somewhere sensible on success — not lost at the top of the page.
// 5. Shrink the viewport to 320px and confirm no state overflows or clips the error message or retry button. Note the smallest width each state survives.
// Local execution is practice feedback only; it cannot create mastery evidence.

const states = [
  { kind: 'loading' },
  { kind: 'empty' },
  { kind: 'error', message: 'Network down' },
  { kind: 'success', orders: [{ id: 'A1' }, { id: 'A2' }, { id: 'A3' }] },
  { kind: 'success', orders: [] },
];

function renderStatus(status) {
  // TODO: implement the accessible UI decision against every supplied state and boundary.
  // Keep loading, empty, error, success, denied, rollback, and keyboard behavior observable.
  throw new Error("complete the frontend evidence decision");
}

for (const s of states) {
  console.log(renderStatus(s));
}

