semantic-html-structure.starter:
// The same panel, rebuilt as a real semantic skeleton
// Mission: Take one real product surface (a content page, an article, or a dashboard panel) and rebuild its skeleton in semantic HTML: one main landmark, a heading outline with no level skips, and every interactive control a real button or link. Then record it as the structure section of your component_state_matrix_and_accessibility_packet.md.
// Novice workflow:
// 1. Enumerate loading, empty, error, success, denied, and rollback states before coding.
// 2. Identify the semantic HTML, keyboard, data, auth, and responsive boundary under test.
// 3. Implement only auditOutline at the TODO.
// 4. Run every fixture, add one failure or accessibility case, and retain it as a regression.
// 5. Explain what must still be proven in a real browser and production-like environment.
// Evidence checklist:
// 1. Open the browser's accessibility-tree inspector: confirm exactly ONE main landmark, and that every <nav> has a distinct accessible name.
// 2. Walk the heading outline top to bottom — h1, then h2, then h3 — and confirm zero skipped levels. A jump from h1 to h3 is a hole; fix it.
// 3. Tab through the page with the mouse untouched: every interactive control must receive focus in source order, and Enter/Space must activate buttons. Anything you can click but not Tab to is a div pretending to be a control.
// 4. For each control, read its line in the accessibility tree: it must have a role (button/link) AND an accessible name. 'clickable, no name' fails WCAG 4.1.2.
// 5. Turn the screen reader's landmark list on: it should let you jump header → nav → main → footer. If main is missing or doubled, the skip-to-content path is broken.
// Local execution is practice feedback only; it cannot create mastery evidence.

const NODES = [
  { tag: "main",    label: null },
  { tag: "header",  label: null },
  { tag: "nav",     label: "Account" },
  { tag: "a",       label: null },
  { tag: "section", label: "recent-heading" },
  { tag: "h1",      label: null },
  { tag: "article", label: null },
  { tag: "button",  label: null },
  { tag: "nav",     label: null },
  { tag: "footer",  label: null },
];

const LANDMARK_ROLES = {
  main: "main",
  header: "banner",
  nav: "navigation",
  section: "region",
  footer: "contentinfo",
};

function auditOutline(nodes) {
  // TODO: implement the accessible UI decision against every supplied state and boundary.
  // Keep loading, empty, error, success, denied, rollback, and keyboard behavior observable.
  throw new Error("complete the frontend evidence decision");
}

const result = auditOutline(NODES);
console.log("landmarks=", result.landmarks);
console.log("roles=", result.roles);
console.log("unnamed=", result.unnamed);

