types-and-ui-contracts.code:
// The contract: one tagged union, illegal states unrepresentable.
type CardState =
  | { status: 'loading' }
  | { status: 'empty' }
  | { status: 'error'; message: string }
  | { status: 'success'; user: User }

function UserCard({ state }: { state: CardState }) {
  switch (state.status) {
    case 'loading':
      return <Skeleton aria-busy="true" aria-label="Loading profile" />
    case 'empty':
      return <Empty>No profile yet — invite this teammate.</Empty>
    case 'error':
      return <Alert role="alert">{state.message} <button>Retry</button></Alert>
    case 'success':
      return <Profile user={state.user} /> // state.user is typed here
    default:
      return assertNever(state) // compile error if a state is unhandled
  }
}

