component-composition.code:
function CheckoutPanel({ cartId }: { cartId: string }) {
  const { data, isLoading, error } = useCart(cartId)

  return (
    <ErrorBoundary fallback={<ErrorState onRetry={() => location.reload()} />}>
      <section aria-labelledby="cart-h" aria-busy={isLoading}>
        <h2 id="cart-h">Your cart</h2>
        {isLoading && <LoadingState />}
        {error && <ErrorState onRetry={() => location.reload()} />}
        {data?.length === 0 && <EmptyState />}
        {data && data.length > 0 && <CartList items={data} />}
      </section>
    </ErrorBoundary>
  )
}

function CheckoutPanel({ cartId }: { cartId: string }) {
