        <h2 id="cart-h">Your cart</h2>
        {isLoading && <LoadingState />}
        {error && <ErrorState onRetry={() => location.reload()} />}
        {data?.length === 0 && <EmptyState />}
        {data && data.length > 0 && <CartList items={data} />}
      </section>
    </ErrorBoundary>
  )
}

component-composition.starter:
// Composing the panel — assembling parts, not stacking flags
// Mission: Take one user-facing surface (a checkout panel, a search box, a profile form) and compose it from small, single-job components — then write component_state_matrix_and_accessibility_packet.md that maps every state (loading, empty, error, disabled, success) to which composed piece owns it.
// Novice workflow:
// 1. Enumerate loading, empty, error, success, denied, and rollback states before coding.
// 2. Identify the semantic HTML, keyboard, data, auth, and responsive boundary under test.
// 3. Implement only renderCart at the TODO.
// 4. Run every fixture, add one failure or accessibility case, and retain it as a regression.
// 5. Explain what must still be proven in a real browser and production-like environment.
// Evidence checklist:
// 1. Open your packet's state matrix: every one of the five states (loading, empty, error, disabled, success) maps to a named component that owns it. A blank cell is a missing state.
// 2. Force the error path: throw inside a child. The ErrorBoundary must render <ErrorState> — if the app blanks, your repair path is missing, not optional.
// 3. Tab through the rendered surface. Every interactive part (retry, submit, links) is reachable in a sane order and shows a visible focus ring — composition does not excuse you from keyboard access.
// 4. Confirm no single component renders more than one state through conditionals. If one part has isLoading && isError && hasData nesting, split it — that is the monolith, not composition.
// 5. Shrink the viewport to 320px. Each composed part should reflow independently; if one part breaking layout drags the others, they are too coupled to be called composed.
// Local execution is practice feedback only; it cannot create mastery evidence.

const LoadingState = () => "LOADING";
const ErrorState = () => "ERROR";
const EmptyState = () => "EMPTY";
const CartList = (items) => "CART(" + items.map((i) => i.name).join(",") + ")";

const states = [
  { isLoading: true, error: null, data: null },
  { isLoading: false, error: "network", data: null },
  { isLoading: false, error: null, data: [] },
  { isLoading: false, error: null, data: [{ name: "boots" }, { name: "hat" }] },
];

function renderCart(state) {
  // TODO: implement the accessible UI decision against every supplied state and boundary.
  // Keep loading, empty, error, success, denied, rollback, and keyboard behavior observable.
  throw new Error("complete the frontend evidence decision");
}

console.log(states.map(renderCart).join(" | "));

