type Status = 'idle' | 'disabled' | 'loading' | 'empty' | 'error' | 'success'
type Event =
  | { type: 'VALIDATE' } | { type: 'INVALIDATE' }
  | { type: 'SUBMIT' } | { type: 'RESOLVE'; count: number }
  | { type: 'REJECT'; message: string } | { type: 'RETRY' }

interface State { status: Status; error?: string }

function reducer(state: State, event: Event): State {
  switch (state.status) {
    case 'idle':
      if (event.type === 'INVALIDATE') return { status: 'disabled' }
      if (event.type === 'SUBMIT')     return { status: 'loading' }
      return state
    case 'disabled':
      return event.type === 'VALIDATE' ? { status: 'idle' } : state
    case 'loading':
      if (event.type === 'RESOLVE') return { status: event.count > 0 ? 'success' : 'empty' }
      if (event.type === 'REJECT')  return { status: 'error', error: event.message }
      return state
    case 'error':
      return event.type === 'RETRY' ? { status: 'loading' } : state
    default:
      return state
  }
}

