function SearchResults({ query }: { query: string }) {
  const { data, error, isPending } = useQuery({
    queryKey: ['search', query],
    queryFn: () => searchApi(query),
  })

  // 1. LOADING — skeleton, not a blank box; signal busy to AT
  if (isPending) {
    return <ResultsSkeleton aria-busy="true" aria-label="Loading results" />
  }

  // 2. ERROR — explain + recover; announce assertively
  if (error) {
    return (
      <div role="alert">
        <p>Couldn’t load results. {getErrorMessage(error)}</p>
        <button onClick={() => refetch()}>Retry</button>
      </div>
    )
  }

  // 3. EMPTY — a designed state, not the absence of one
  if (data.length === 0) {
    return (
      <EmptyState
        title={`No results for “${query}”`}
        action="Try a broader term or check spelling"
      />
    )
  }

  // 4. SUCCESS — the data, with a live region for the count
  return (
    <ul aria-live="polite">
      <p className="sr-only">{data.length} results</p>
      {data.map((r) => <ResultRow key={r.id} result={r} />)}
    </ul>
  )
}

