import { z } from 'zod'

// 1. The contract: the exact shape the UI is allowed to depend on.
const OrderSchema = z.object({
  id: z.string(),
  status: z.enum(['pending', 'shipped', 'delivered']),
  total: z.number().nonnegative(),
})
const OrdersResponse = z.object({ orders: z.array(OrderSchema) })

// 2. The type is INFERRED from the contract — one source of truth.
export type Order = z.infer<typeof OrderSchema>

// 3. The typed client: validates at the boundary, never returns `any`.
export async function fetchOrders(): Promise<Order[]> {
  const res = await fetch('/api/orders')
  if (!res.ok) throw new ApiError(res.status, 'orders request failed')
  const json: unknown = await res.json()        // untrusted
  const parsed = OrdersResponse.parse(json)      // contract enforced here
  return parsed.orders
}

export class ApiError extends Error {
  constructor(public status: number, message: string) { super(message) }
}

