function OrdersTable() {
  const [params, setParams] = useSearchParams()
  const status = params.get('status') ?? 'all'
  const page = Number(params.get('page') ?? '1')

  // The query string IS the cache key — refresh reproduces this view exactly.
  const { data, error, isLoading } = useOrders({ status, page, limit: 25 })

  function setFilter(next: string) {
    setParams({ status: next, page: '1' }) // new filter resets to page 1
  }

  if (isLoading) return <TableSkeleton rows={25} aria-busy="true" />
  if (error) return <ErrorState onRetry={() => setParams(params)} />
  if (data.rows.length === 0) return <EmptyState status={status} onClear={() => setFilter('all')} />

  return (
    <>
      <FilterBar status={status} onChange={setFilter} />
      <table aria-live="polite">{/* rows */}</table>
      <Pager page={page} total={data.total} onPage={(p) => setParams({ status, page: String(p) })} />
    </>
  )
}

