type Point = { label: string; value: number }
type State =
  | { kind: 'loading' }
  | { kind: 'empty' }
  | { kind: 'error'; message: string }
  | { kind: 'success'; data: Point[] }

export function MetricsChart({ range }: { range: string }) {
  const [state, setState] = useState<State>({ kind: 'loading' })

  useEffect(() => {
    let live = true
    setState({ kind: 'loading' })
    fetch(`/api/metrics?range=${range}`)
      .then(async (res) => {
        if (!res.ok) throw new Error(`Metrics unavailable (${res.status})`)
        const json = (await res.json()) as { points: Point[] }
        if (!live) return
        setState(
          json.points.length === 0
            ? { kind: 'empty' }
            : { kind: 'success', data: json.points },
        )
      })
      .catch((e) => live && setState({ kind: 'error', message: e.message }))
    return () => { live = false }
  }, [range])

  if (state.kind === 'loading')
    return <Skeleton aria-busy="true" label="Loading revenue" />
  if (state.kind === 'empty')
    return <Empty>No revenue in this range.</Empty>
  if (state.kind === 'error')
    return <ErrorState message={state.message} onRetry={() => setRange(range)} />

  return (
    <figure>
      <BarChart data={state.data} aria-hidden="true">{/* bars */}</BarChart>
      <figcaption className="sr-only">
        Revenue by day: {state.data.map((p) => `${p.label} ${p.value}`).join(', ')}
      </figcaption>
    </figure>
  )
}

