'use client'
import { useQuery } from '@tanstack/react-query'
import { useRouter } from 'next/navigation'

export function OrderDetail({ id }: { id: string }) {
  const router = useRouter()
  const { data, status, refetch } = useQuery({
    queryKey: ['order', id],
    queryFn: () => fetchOrder(id), // resolves Order | null
  })

  if (status === 'pending') return <DetailSkeleton />        // loading
  if (status === 'error')
    return <ErrorState onRetry={() => refetch()} />          // error
  if (data === null)
    return <EmptyState message={`Order ${id} not found`} />  // empty / 404

  return (
    <article aria-labelledby="order-title">                 {/* success */}
      <h1 id="order-title">Order {data.number}</h1>
      <OrderSummary order={data} />
      <button onClick={() => router.push('/orders')}>Back to orders</button>
    </article>
  )
}

