export function useToggleFollow(userId: string) {
  const qc = useQueryClient()
  const announce = useLiveAnnounce() // writes into an aria-live region

  return useMutation({
    mutationFn: (next: boolean) =>
      api.post(`/users/${userId}/follow`, { following: next }, {
        headers: { 'Idempotency-Key': `follow:${userId}:${next}` },
      }),

    onMutate: async (next) => {
      await qc.cancelQueries({ queryKey: ['user', userId] })
      const prev = qc.getQueryData<User>(['user', userId])       // 1. snapshot
      qc.setQueryData<User>(['user', userId], (u) =>             // 2. apply now
        u ? { ...u, isFollowing: next } : u)
      return { prev }                                            // 3. hand snapshot to onError
    },

    onError: (_err, _next, ctx) => {
      if (ctx?.prev) qc.setQueryData(['user', userId], ctx.prev) // 4. roll back
      announce('Could not update follow. Reverted — try again.') // 5. tell the user
    },

    onSettled: () => qc.invalidateQueries({ queryKey: ['user', userId] }), // 6. reconcile w/ truth
  })
}

export function useToggleFollow(userId: string) {
  const qc = useQueryClient()
  const announce = useLiveAnnounce() // writes into an aria-live region

  return useMutation({
    mutationFn: (next: boolean) =>
      api.post(`/users/${userId}/follow`, { following: next }, {
        headers: { 'Idempotency-Key': `follow:${userId}:${next}` },
      }),

    onMutate: async (next) => {
      await qc.cancelQueries({ queryKey: ['user', userId] })
      const prev = qc.getQueryData<User>(['user', userId])       // 1. snapshot
      qc.setQueryData<User>(['user', userId], (u) =>             // 2. apply now
        u ? { ...u, isFollowing: next } : u)
      return { prev }                                            // 3. hand snapshot to onError
    },

    onError: (_err, _next, ctx) => {
      if (ctx?.prev) qc.setQueryData(['user', userId], ctx.prev) // 4. roll back
      announce('Could not update follow. Reverted — try again.') // 5. tell the user
    },

    onSettled: () => qc.invalidateQueries({ queryKey: ['user', userId] }), // 6. reconcile w/ truth
  })
}

