// middleware.ts — runs at the edge, before the route renders
import { NextResponse, type NextRequest } from 'next/server'
import { getSession } from '@/lib/auth'

export async function middleware(req: NextRequest) {
  const session = await getSession(req)
  if (!session) {
    const url = new URL('/login', req.url)
    url.searchParams.set('next', req.nextUrl.pathname)
    return NextResponse.redirect(url) // 307 — private page never renders
  }
  return NextResponse.next()
}

export const config = { matcher: ['/dashboard/:path*'] }

// app/dashboard/page.tsx — Server Component, re-verifies before any fetch
import { redirect } from 'next/navigation'
import { getSession } from '@/lib/auth'
import { getUserDashboard } from '@/lib/data'

export default async function DashboardPage() {
  const session = await getSession()
  if (!session) redirect('/login') // belt-and-suspenders: cookie present != valid

  const data = await getUserDashboard(session.userId) // scoped to THIS user
  return <Dashboard data={data} />
}

