import { test, expect } from '@playwright/test'

const VIEWPORTS = [320, 768, 1024, 1440]
const STATES = ['loading', 'empty', 'error', 'disabled', 'success'] as const

for (const width of VIEWPORTS) {
  for (const state of STATES) {
    test(`checkout · ${state} @ ${width}px`, async ({ page }) => {
      await page.setViewportSize({ width, height: 900 })
      await page.goto(`/checkout?state=${state}`)

      // 1. State actually rendered (no silent fallthrough to success)
      await expect(page.getByTestId(`state-${state}`)).toBeVisible()

      // 2. No horizontal overflow — the 320px killer
      const overflow = await page.evaluate(
        () => document.documentElement.scrollWidth - document.documentElement.clientWidth,
      )
      expect(overflow, 'horizontal overflow').toBeLessThanOrEqual(0)

      // 3. Keyboard reaches the primary control and focus stays visible
      await page.keyboard.press('Tab')
      await expect(page.getByRole('button', { name: /pay|retry/i })).toBeFocused()

      // 4. Evidence: one screenshot per cell of the matrix
      await page.screenshot({ path: `proof/checkout-${state}-${width}.png` })
    })
  }
}

