// Writing the proof: walk every cell, capture evidence
// Mission: Take one real component that has multiple states (loading, empty, error, disabled, success) and produce Responsive Visual Proof: a state × viewport matrix, a Playwright flow that walks every cell, a keyboard checklist, and named viewport-failure screenshots — packaged as component_state_matrix_and_accessibility_packet.md.
// Novice workflow:
// 1. Enumerate loading, empty, error, success, denied, and rollback states before coding.
// 2. Identify the semantic HTML, keyboard, data, auth, and responsive boundary under test.
// 3. Implement only auditViewport at the TODO.
// 4. Run every fixture, add one failure or accessibility case, and retain it as a regression.
// 5. Explain what must still be proven in a real browser and production-like environment.
// Evidence checklist:
// 1. Every state (loading, empty, error, disabled, success) appears at every breakpoint (320, 768, 1024, 1440) — count the cells, not the screenshots you happened to take.
// 2. The 320px cell of the error state has a screenshot AND a passing no-horizontal-overflow assertion. If the error toast overflows, that's a real failure to log, not a cell to skip.
// 3. A keyboard-only pass reaches the primary action and focus is visible at each cell (WCAG 2.2 SC 2.4.7 Focus Visible; SC 2.4.11 Focus Not Obscured for overlay cases) — recorded as a checklist, not a memory.
// 4. The error state was triggered by a real failure path (a mocked 500 or thrown error boundary), not faked by a ?state=error that silently renders success.
// 5. The Playwright flow re-runs green from a clean checkout — a reviewer can reproduce your evidence without you, or it is your screenshot, not proof.
// Local execution is practice feedback only; it cannot create mastery evidence.

const VIEWPORTS = [320, 768, 1024, 1440];
const REQUIRED_STATES = ["loading", "empty", "error", "disabled", "success"];

const CAPTURES = {
  320:  { contentWidth: 360, renderedStates: ["loading", "empty", "error", "disabled", "success"] },
  768:  { contentWidth: 768, renderedStates: ["loading", "empty", "error", "disabled", "success"] },
  1024: { contentWidth: 1024, renderedStates: ["loading", "empty", "error", "success"] },
  1440: { contentWidth: 1440, renderedStates: ["loading", "empty", "error", "disabled", "success"] },
};

function auditViewport(width, capture) {
  // TODO: implement the accessible UI decision against every supplied state and boundary.
  // Keep loading, empty, error, success, denied, rollback, and keyboard behavior observable.
  throw new Error("complete the frontend evidence decision");
}

const results = VIEWPORTS.map((w) => auditViewport(w, CAPTURES[w]));
const failures = results.filter((r) => !r.pass);

for (const r of results) {
  console.log(r.width + "px", "overflow=" + r.overflow, "missing=" + JSON.stringify(r.missing), r.pass ? "PASS" : "FAIL");
}
console.log("failures=", failures.length);

