// Testing the five states, one assertion at a time
// Mission: Take one real component that has more than a happy path (a form, a data list, an async panel) and write its Frontend Testing Strategy: a state matrix covering loading, empty, error, disabled, and success, each row mapped to the cheapest test layer that proves it, plus a keyboard + viewport accessibility check that a happy-path test would never catch.
// Novice workflow:
// 1. Enumerate loading, empty, error, success, denied, and rollback states before coding.
// 2. Identify the semantic HTML, keyboard, data, auth, and responsive boundary under test.
// 3. Implement only runInSearchPanelTests at the TODO.
// 4. Run every fixture, add one failure or accessibility case, and retain it as a regression.
// 5. Explain what must still be proven in a real browser and production-like environment.
// Evidence checklist:
// 1. Point to the test that fails if the empty state renders a blank box instead of a 'no results' message. If there is none, your success test is masking the empty state.
// 2. Point to the test that fails if a 500 unmounts the tree instead of hitting the error boundary. Force the mock to reject and watch it go red.
// 3. Click your disabled control inside a test and assert nothing fired — 'looks gray' is not 'is disabled'.
// 4. Run one Playwright flow with keyboard only: tab to the field, type, Enter to submit, and assert focus lands somewhere sane. WCAG 2.2 keyboard-operable is non-negotiable.
// 5. Render the component at a 320px viewport and assert no horizontal overflow. Note the screenshot. The narrowest real phone is the cheapest a11y regression to catch.
// Local execution is practice feedback only; it cannot create mastery evidence.

function describeSearchPanel(props) {
  const { state, results, query } = props;
  if (state === "loading") return { role: "status", text: "Searching...", ctaEnabled: false };
  if (state === "error")   return { role: "alert",  text: "Try again",   ctaEnabled: true  };
  if (state === "success") {
    const n = (results || []).length;
    if (n === 0) return { role: "status", text: "No results", ctaEnabled: false };
    return { role: "list", text: n + " results", ctaEnabled: true };
  }
  if (!query) return { role: "search", text: "Type to search", ctaEnabled: false };
  return { role: "search", text: "Ready", ctaEnabled: true };
}

