// Wiring the five states into one workflow
// Mission: Take one real user-facing workflow (a form that posts to an API, a list that fetches) and build its component_state_matrix_and_accessibility_packet.md: every UI state the workflow can occupy — loading, empty, error, disabled, success — wired to a verified API behavior, plus the accessibility evidence (keyboard path + screen-reader announcement) that each state actually reaches the user.
// Novice workflow:
// 1. Enumerate loading, empty, error, success, denied, and rollback states before coding.
// 2. Identify the semantic HTML, keyboard, data, auth, and responsive boundary under test.
// 3. Implement only toStatus at the TODO.
// 4. Run every fixture, add one failure or accessibility case, and retain it as a regression.
// 5. Explain what must still be proven in a real browser and production-like environment.
// Evidence checklist:
// 1. Open the state matrix: every row (loading, empty, error, disabled, success) has an API condition that triggers it and a component-state transition that renders it. No row says 'TODO'.
// 2. Drive the error path: mock a 500 (or kill the network) and confirm the UI shows a readable message, the submit re-enables, and focus lands on the message — not a frozen spinner.
// 3. Drive the empty path: return a 200 with no result and confirm a real empty state renders, distinct from both loading and error.
// 4. Run the keyboard checklist: reach submit by Tab alone, trigger each state, and confirm the aria-live region announces success (polite) and error (assertive) — verified with VoiceOver or NVDA, not assumed.
// 5. Record the viewport failure note: shrink to 320px and confirm no state overflows or hides the error message off-screen.
// 6. Confirm the Playwright flow is committed and green, and the packet is attached to the evidence ledger by name.
// Local execution is practice feedback only; it cannot create mastery evidence.

const SCENARIOS = [
  { email: 'ada@dev.io',  res: { ok: true,  status: 200, created: true  } },
  { email: 'lin@dev.io',  res: { ok: true,  status: 200, created: false } },
  { email: 'bad@dev.io',  res: { ok: false, status: 429 } },
  { email: 'rex@dev.io',  res: { ok: false, status: 500 } },
];

function toStatus(email, res) {
  // TODO: implement the accessible UI decision against every supplied state and boundary.
  // Keep loading, empty, error, success, denied, rollback, and keyboard behavior observable.
  throw new Error("complete the frontend evidence decision");
}

function describe(status) {
  const disabled = status.kind === 'loading';
  let announce = '';
  if (status.kind === 'success') announce = `Subscribed ${status.email}`;
  else if (status.kind === 'empty') announce = 'Already subscribed';
  else if (status.kind === 'error') announce = status.message;
  return { disabled, announce };
}

for (const s of SCENARIOS) {
  const status = toStatus(s.email, s.res);
  const view = describe(status);
  console.log(status.kind, JSON.stringify(view));
}

