type Status = 'idle' | 'loading' | 'success' | 'error'

function CheckoutForm({ onPlace }: { onPlace: (cart: Cart) => Promise<Order> }) {
  const [status, setStatus] = useState<Status>('idle')
  const [error, setError] = useState<string | null>(null)
  const [cart] = useCart()
  const isEmpty = cart.items.length === 0
  const liveRef = useRef<HTMLDivElement>(null)

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault()
    if (isEmpty || status === 'loading') return // disabled gate
    setStatus('loading'); setError(null)
    try {
      const order = await onPlace(cart)
      setStatus('success')
      liveRef.current?.focus() // move focus to the result
    } catch (err) {
      setStatus('error')
      setError(getErrorMessage(err)) // input is NOT cleared
    }
  }

  if (isEmpty) return <EmptyCart />          // empty state
  return (
    <form onSubmit={handleSubmit} aria-busy={status === 'loading'}>
      <fieldset disabled={status === 'loading'}>
        <CartSummary cart={cart} />
        <button type="submit">
          {status === 'loading' ? 'Placing order…' : 'Place order'}
        </button>
      </fieldset>
      <div ref={liveRef} tabIndex={-1} role="status" aria-live="polite">
        {status === 'success' && <p>Order confirmed.</p>}
        {status === 'error' && <p role="alert">{error} — your cart is saved, try again.</p>}
      </div>
    </form>
  )
}

type Status = 'idle' | 'loading' | 'success' | 'error'

function CheckoutForm({ onPlace }: { onPlace: (cart: Cart) => Promise<Order> }) {
  const [status, setStatus] = useState<Status>('idle')
  const [error, setError] = useState<string | null>(null)
  const [cart] = useCart()
  const isEmpty = cart.items.length === 0
  const liveRef = useRef<HTMLDivElement>(null)

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault()
    if (isEmpty || status === 'loading') return // disabled gate
    setStatus('loading'); setError(null)
    try {
      const order = await onPlace(cart)
      setStatus('success')
      liveRef.current?.focus() // move focus to the result
    } catch (err) {
      setStatus('error')
      setError(getErrorMessage(err)) // input is NOT cleared
    }
  }

  if (isEmpty) return <EmptyCart />          // empty state
  return (
    <form onSubmit={handleSubmit} aria-busy={status === 'loading'}>
      <fieldset disabled={status === 'loading'}>
        <CartSummary cart={cart} />
        <button type="submit">
          {status === 'loading' ? 'Placing order…' : 'Place order'}
        </button>
      </fieldset>
      <div ref={liveRef} tabIndex={-1} role="status" aria-live="polite">
        {status === 'success' && <p>Order confirmed.</p>}
        {status === 'error' && <p role="alert">{error} — your cart is saved, try again.</p>}
      </div>
    </form>
  )
}

