  throw new Error("complete the frontend evidence decision");
}

const actions = [
  { type: 'submit' },
  { type: 'submit' },
  { type: 'reject', message: 'card declined' },
  { type: 'submit' },
  { type: 'resolve' },
];

let state = initialState;
const trace = [];
for (const action of actions) {
  state = reducer(state, action);
  trace.push(state.status);
}
console.log("trace", trace);
console.log("final", state);
console.log("itemsKept", state.items.length === initialState.items.length);

